/*=============================================================================
	AkSrcPhysModel.h - CAkSrcPhysModel (aksrcphysmodel.cpp/.h): a source generated by a source plug-in (an FX custom
	object whose ID is the source ID), e.g. the Wwise Silence source.

	DISHONORED(port): agent IH2 fork S (wave 26). Layout is the 2012 PDB's (80 bytes, CAkVPLSrcNode::Create mallocs 0x50).
	Dishonored's banks do hold such sources (AkSilenceSource, plug-in ID 0x650002, 40 of them), so Create builds this
	node as retail does; agent IH4 runs the plug-in through it (AkSrcPhysModel.cpp).
=============================================================================*/
#pragma once

#include "AkVPLNode.h"

#include <AK/SoundEngine/Common/IAkPlugin.h>
class CAkSourceFXContext;

class CAkSrcPhysModel : public CAkVPLSrcNode
{
public:
	explicit CAkSrcPhysModel( CAkPBI * in_pCtx );

	virtual void ReleaseBuffer();
	virtual AKRESULT TimeSkip( AkUInt32 & io_uFrames );
	virtual void VirtualOn( AkVirtualQueueBehavior eBehavior );
	virtual AKRESULT StartStream();
	virtual void StopStream();
	virtual void GetBuffer( AkVPLState & io_state );
	virtual AkReal32 GetDuration() const;
	virtual AKRESULT StopLooping();
	virtual void * GetPluginParam() { return m_pParam; }
	virtual AKRESULT ChangeSourcePosition();

	AkPluginID m_FXID;
	AK::IAkPluginParam * m_pParam;
	AK::IAkSourcePlugin * m_pEffect;
	AkPipelineBuffer m_pluginBuffer;
	CAkSourceFXContext * m_pSourceFXContext;
	AkAudioFormat m_AudioFormat;
};
static_assert( sizeof( CAkSrcPhysModel ) == 0x50, "CAkSrcPhysModel: CAkVPLSrcNode::Create mallocs 0x50" );
